  function trackingCards(list,editable){return `<section class="tracking-manager"><div class="tracking-manager-head"><div><p class="eyebrow">${es('SEGUIMIENTO DE COMPRA','PURCHASE TRACKING')}</p><h2>${es('Tracking de órdenes','Order tracking')}</h2></div></div><div class="tracking-list">${list.length?list.map(order=>{let index=currentView.state.orders.findIndex(x=>x.id===order.id),editor=order.trackingUpdatedBy;return `<article class="tracking-card" data-tracking-search="${trackingNumber(order,index).toLowerCase()}"><div><strong>${trackingNumber(order,index)}</strong><small>${escape(order.number)} · ${escape(order.supplier)}</small></div><span class="tracking-status">${trackingLabel(order.trackingStatus)}</span><small>${es('Último en editar:','Last edited by:')} ${escape(editor?.username||'—')}${editor?.name?` · ${escape(editor.name)}`:''}</small>${editable?`<div class="tracking-actions"><button class="secondary" data-preview-tracking="${order.id}" aria-label="${es('Ver orden','View order')}">${icon('eye')}</button><button class="secondary" data-download-tracking="${order.id}" aria-label="${es('Descargar orden','Download order')}">↓</button><button class="secondary tracking-edit" data-edit-tracking="${order.id}" aria-label="${es('Editar tracking','Edit tracking')}">${icon('edit')}</button><button class="danger tracking-delete" data-delete-project-order="${order.id}" aria-label="${es('Eliminar orden de compra','Delete purchase order')}">${icon('trash')}</button></div>`:''}</article>`}).join(''):`<p class="empty">${es('Aún no hay órdenes para seguir.','There are no orders to track yet.')}</p>`}</div></section>`}
