  document.addEventListener('change',event=>{let input=event.target;if(input.name!=='profilePhoto'||!input.closest('#profile-photo-form'))return;let file=input.files?.[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{let form=input.closest('#profile-photo-form'),image=new Image();image.onload=()=>{form._cropState={image,left:null,top:null,adjusting:false};form.querySelector('.profile-cropper').hidden=false;form.querySelector('[data-profile-adjust]').disabled=false;form.querySelector('[data-profile-crop="zoom"]').disabled=false;refreshProfileCrop(form)};image.src=reader.result};reader.readAsDataURL(file)},true);
