  function invoiceSection(){if(currentView?.route!=='project'||!['Admin','Worker'].includes(currentView.user.role))return;let project=currentView.state.projects.find(p=>p.id===currentView.selectedProjectId),host=document.querySelector('.project-purchase-section');if(!project||!host||host.parentElement.querySelector('.project-invoice-section'))return;let invoices=project.invoices||[];host.insertAdjacentHTML('afterend',`<section class="section project-invoice-section"><div class="section-head"><div><p class="eyebrow">${es('GESTIÓN FINANCIERA','FINANCIAL MANAGEMENT')}</p><h2>${es('Emisión de factura','Invoice issuance')}</h2></div><button class="primary" data-new-invoice="${project.id}">${icon('plus')} ${es('Generar nueva factura','Generate new invoice')}</button></div><div class="invoice-history">${invoices.length?invoices.map(invoice=>`<article class="invoice-record"><div><strong>${escape(invoice.number)}</strong><small>${escape(invoice.invoiceNumber||es('Factura sin número','Invoice without number'))} · ${escape(invoice.requestDate||'—')}</small></div><span>${escape(invoice.currency||'S/')} ${escape(invoice.totalRequest||'0.00')}</span><button class="secondary" data-preview-invoice="${invoice.id}" data-project-id="${project.id}">${icon('eye')} ${es('Ver','View')}</button><button class="danger invoice-delete" data-delete-invoice="${invoice.id}" data-project-id="${project.id}" aria-label="${es('Eliminar factura','Delete invoice')}">${icon('trash')}</button></article>`).join(''):`<p class="empty">${es('Aún no hay facturas emitidas para este proyecto.','There are no invoices issued for this project yet.')}</p>`}</div></section>`)}new MutationObserver(invoiceSection).observe(app,{childList:true,subtree:true});invoiceSection();
